using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using SBCCashier.Web.Models;using SBCCashier.Web.Services;
namespace SBCCashier.Web.Pages.VehiclePasses;
public sealed class IndexModel:PageModel{private readonly CashierStore _store;public IReadOnlyList<VehiclePassRow> Passes{get;private set;}=[];public IReadOnlyList<Student> Students{get;private set;}=[];public string? ErrorMessage{get;private set;}[BindProperty]public VehiclePass NewPass{get;set;}=new();public IndexModel(CashierStore store)=>_store=store;public void OnGet()=>Load();public IActionResult OnPostCreate(){if(string.IsNullOrWhiteSpace(NewPass.PlateNumber)||NewPass.Amount<0){ErrorMessage="Plate number and a valid amount are required.";Load();return Page();}try{_store.AddVehiclePass(NewPass);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}private void Load(){Passes=_store.VehiclePasses;Students=_store.Students;}}
